bounded_host_request.command:
set -euo pipefail
names="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])gaybbs([-_]|$)' || true)"
test "$(printf '%s\n' "$names" | sed '/^$/d' | wc -l)" -eq 1 || { echo STK04_RUNNING_GAYBBS_NOT_UNIQUE; exit 63; }
gay="$names"
img="$(docker inspect -f '{{.Image}}' "$gay")"
token_path="$(docker exec "$gay" node -e 'process.stdout.write(process.env.BOT_TOKEN_FILE||"")')"
test -n "$token_path" || { echo STK04_GROUP_CREDENTIAL_FILE_UNAVAILABLE; exit 64; }
docker run -i --rm --read-only --network host --volumes-from "$gay":ro --security-opt no-new-privileges --env "BOT_TOKEN_FILE=$token_path" --entrypoint node "$img" --input-type=module - <<'STICKER_JS'
import fs from "node:fs";
const raw=fs.readFileSync(process.env.BOT_TOKEN_FILE,"utf8").trim();
if(!/^[0-9]{7,15}:[A-Za-z0-9_-]{30,100}$/.test(raw))throw Error("STK04_GROUP_BOT_TOKEN_INVALID");
const chatId=-1002373696859;
const anchor=4640;
const link="https://t.me/CreateVdobot?start=sticker";
async function bot(method,params){
 const controller=new AbortController();
 const timer=setTimeout(()=>controller.abort(),12000);
 try {
  const response=await fetch("https://api.telegram.org/bot"+raw+"/"+method,{
   method:"POST",headers:{"content-type":"application/json"},
   body:JSON.stringify(params),signal:controller.signal
  });
  const j=await response.json();
  if(!response.ok||j.ok!==true)throw Error("STK04_TELEGRAM_"+method+"_REJECTED_"+String(j.error_code??"UNKNOWN"));
  return j.result;
 }finally{clearTimeout(timer);}
}
try{
 const me=await bot("getMe",{});
 if(me.is_bot!==true||me.username?.toLowerCase()!=="gaybbs_bot")throw Error("STK04_GROUP_BOT_IDENTITY_INVALID");
 const c=await bot("getChat",{chat_id:chatId});
 if(Number(c.id)!==chatId||c.type!=="supergroup"||c.is_forum!==true)throw Error("STK04_TARGET_GROUP_NOT_FORUM");
 const m=await bot("getChatMember",{chat_id:chatId,user_id:me.id});
 if(!["administrator","creator"].includes(m.status)||(m.status==="administrator"&&m.can_pin_messages!==true))throw Error("STK04_PIN_RIGHTS_MISSING");
 console.log("STK04_GROUP_ADMIN_VERIFIED");
 let sent;
 try{
  sent=await bot("sendMessage",{
   chat_id:chatId,
   reply_parameters:{message_id:anchor,allow_sending_without_reply:false},
   text:"🎨 ステッカー作成・投稿はこちら\n下のボタンからCreateVdobotのDMへ移動できます。",
   reply_markup:{inline_keyboard:[[{text:"🎨 投稿はこちら",url:link}]]},
   disable_notification:true
  });
 }catch(e){console.log("STK04_SEND_NOT_CONFIRMED");throw e;}
 if(!Number.isSafeInteger(sent?.message_id)||sent.message_id<=0){console.log("STK04_SEND_RESULT_UNKNOWN");throw Error("STK04_SEND_RESULT_UNKNOWN");}
 console.log("STK04_POST_MESSAGE_ID="+sent.message_id);
 console.log("STK04_POST_THREAD_ID="+(sent.message_thread_id??"UNVERIFIED"));
 if(sent.is_topic_message!==true){console.log("STK04_POST_NOT_TOPIC");throw Error("STK04_TOPIC_MEMBERSHIP_UNVERIFIED");}
 const pinned=await bot("pinChatMessage",{chat_id:chatId,message_id:sent.message_id,disable_notification:true});
 if(pinned!==true)throw Error("STK04_PIN_RESULT_UNKNOWN");
 console.log("STK04_PIN_API_ACK=PASS");
 console.log("STK04_DM_TARGET=CREATEVDOBOT");
}catch(error){
 const msg=String(error?.message??"UNKNOWN");
 console.error(msg.startsWith("STK04_")?msg:"STK04_API_RESULT_UNKNOWN");
 process.exitCode=1;
}
STICKER_JS
